// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(c).balance + 1);
        vm.deal(address(c), amount + 1 ether);
        vm.prank(caller);
        try c.withdraw(amount) {
            if (caller != c.owner()) {
                assertTrue(false);
            }
        } catch {
            if (caller == c.owner()) {
                assertTrue(false);
            }
        }
        assertTrue(true);
    }
}
